alter table public.profiles enable row level security;alter table public.providers enable row level security;alter table public.incidents enable row level security;alter table public.ingestion_runs enable row level security;alter table public.subscriptions enable row level security;
create policy profiles_own_select on public.profiles for select to authenticated using(auth.uid()=id);create policy profiles_own_update on public.profiles for update to authenticated using(auth.uid()=id) with check(auth.uid()=id);
create policy providers_enabled_read on public.providers for select to anon,authenticated using(enabled=true);create policy incidents_enabled_read on public.incidents for select to anon,authenticated using(exists(select 1 from public.providers p where p.id=provider_id and p.enabled=true));
create policy subscriptions_own_read on public.subscriptions for select to authenticated using(auth.uid()=user_id);create policy subscriptions_own_insert on public.subscriptions for insert to authenticated with check(auth.uid()=user_id);create policy subscriptions_own_delete on public.subscriptions for delete to authenticated using(auth.uid()=user_id);
create or replace function public.create_profile_for_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,display_name) values(new.id,coalesce(new.raw_user_meta_data->>'name',split_part(new.email,'@',1)));return new;end;$$;
create trigger auth_user_profile after insert on auth.users for each row execute procedure public.create_profile_for_user();
grant select on public.providers,public.incidents to anon,authenticated;grant select,update on public.profiles to authenticated;grant select,insert,delete on public.subscriptions to authenticated;